'use strict';
const C=CTCS,$=id=>document.getElementById(id);let cfg=C.loadConfig(),history=[],checking=false,canManageConnection=true;
const textFields=['train','driver','mode','device','displayScale','control','upDown'];
const numberFields=['level','cars','zoom','brightness','volume'];
const checkFields=['bezel','autoRoute','lkjVoice'];
const sound=new DmiSound();let currentFrame=null,editingRoute='';
const connectionFields=['baseUrl','keyFile','speedEndpoint','speedField','speedUnit','aidEndpoint','aidSpeedUnit','aidDistanceUnit','trackEndpoint'];
for(let [key,name]of Object.entries(C.MODES)){let option=document.createElement('option');option.value=key;option.textContent=name;$('mode').appendChild(option);$('route-mode').appendChild(option.cloneNode(true))}
function notice(text,error=false){$('notice').textContent=text;$('notice').style.borderLeftColor=error?'#d17c7c':'#bad2e2'}
function populate(){for(let k of textFields.concat(numberFields))$(k).value=cfg[k];for(let k of checkFields)$(k).checked=!!cfg[k];for(let k of ['brightness','volume'])$(k+'-value').value=cfg[k]+'%'}
function save(){try{for(let k of textFields)cfg[k]=$(k).value;for(let k of numberFields){let v=Number($(k).value);if(!Number.isFinite(v))throw Error('请输入有效数值');cfg[k]=v}for(let k of checkFields)cfg[k]=$(k).checked;cfg=C.saveConfig(cfg);populate();notice('已保存，主屏同步应用。')}catch(e){notice(e.message,true)}}
function navigate(){let id=location.hash.slice(1)||'connection';if(!canManageConnection&&id==='diagnostics')id='display';if(!$(id)||!$(id).classList.contains('section'))id='connection';for(let section of document.querySelectorAll('.section'))section.hidden=section.id!==id;for(let a of document.querySelectorAll('nav a'))a.classList.toggle('selected',a.getAttribute('href')==='#'+id);$('page-title').textContent=({connection:'TSW 连接',route:'线路与制动',display:'界面与声音',diagnostics:'接口诊断',scope:'复刻依据'})[id];$('notice').textContent=''}
window.addEventListener('hashchange',navigate);
for(let button of document.querySelectorAll('.save-config'))button.onclick=save;
for(let k of ['brightness','volume'])$(k).oninput=()=>{cfg[k]=Number($(k).value);$(k+'-value').value=cfg[k]+'%';cfg=C.saveConfig(cfg)};
$('connect').onclick=async()=>{let button=$('connect');button.disabled=true;try{let data={};for(let k of connectionFields)data[k]=$(k).value.trim();data.key=$('key').value;let result=await C.api.post('/api/connect',data);$('key').value='';$('connection-result').textContent=result.message;notice('已启用 TSW 自动连接。');await checkBridge()}catch(e){notice(e.message,true)}finally{button.disabled=false}};
$('disconnect').onclick=async()=>{try{await C.api.post('/api/disconnect',{});notice('已暂停游戏连接；点击“连接并应用”恢复。');await checkBridge()}catch(e){notice(e.message,true)}};
async function query(){try{let j=await C.api.post('/api/query',{path:$('query-path').value.trim()});$('query-result').textContent=JSON.stringify(j.data,null,2)}catch(e){$('query-result').textContent=e.message}}
$('query').onclick=query;$('list').onclick=()=>{$('query-path').value='/list';query()};$('raw').onclick=async()=>{try{let j=await C.api.get('/api/raw');$('raw-result').textContent='速度响应\n'+j.speed+'\n\n线路响应\n'+j.aid}catch(e){$('raw-result').textContent=e.message}};
function download(name,content,type){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
$('export-config').onclick=()=>download('DMI-settings.json',JSON.stringify(cfg,null,2),'application/json');
$('import-config').onchange=async()=>{try{let f=$('import-config').files[0];if(!f)return;if(f.size>1024*1024)throw Error('设置文件过大');cfg=C.saveConfig(JSON.parse(await f.text()));populate();notice('已导入界面设置。')}catch(e){notice(e.message,true)}};
$('export-csv').onclick=()=>{let out=['timestamp,valid,speed_kmh,limit_kmh,target_kmh,distance_m'];for(let f of history)out.push([f.Timestamp,f.Fresh,...['Speed','Limit','Target','Distance'].map(k=>f.Fresh?f[k]??'':'')].join(','));download('TSW-telemetry.csv','\ufeff'+out.join('\r\n'),'text/csv;charset=utf-8')};
function runtime(f){$('cab-activation').textContent=(f.DmiReady?'DMI 已启动 · ':'DMI 未启动 · ')+(f.CabActivation?.reason||'等待司机室激活状态');currentFrame=f;routeRuntime(f);const n=x=>typeof x==='number'?Math.round(x*10)/10:'—';$('runtime').textContent='TSW 7 · '+(f.GameAdvancing===false?'游戏时间未推进':f.Fresh?'数据有效':'等待游戏')+' · 速度 '+n(f.Speed)+' km/h · 限速 '+n(f.Limit)+' km/h · 目标距离 '+n(f.Distance)+' m'+(f.Station?' · '+f.Station:'');history.push({...f,captured:Date.now()});history=history.filter(x=>Date.now()-x.captured<900000)}
window.addEventListener('storage',e=>{if(e.key===C.CONFIG_KEY){if(document.activeElement&&['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;cfg=C.loadConfig();populate()}});
let controlLinkSignature='';
function refreshControlLinks(){const signature=JSON.stringify([C.api.canManageConnection,C.api.controlToken,C.api.lanUrls]);if(signature===controlLinkSignature)return;controlLinkSignature=signature;if(C.api.controlToken){let box=$('control-links');box.textContent='局域网操纵已默认开启，直接打开以下页面：';for(let url of C.api.lanUrls||[])for(let [page,label]of [['index.html','主屏与 ATO 按钮'],['ato.html','ATO 与 PID 设置'],['control.html','手动制动']]){let a=document.createElement('a');a.href=url+page;a.textContent=label+' · '+url;a.target='ctcs-control';box.append(document.createElement('br'),a)}}else $('control-links').textContent='正在连接桥接，连接后自动启用操纵。'}
async function checkBridge(){if(checking)return;checking=true;try{
 let data,frame;try{[data,frame]=await Promise.all([C.api.get('/api/status'),C.api.get('/api/frame')])}catch(e){$('bridge-status').textContent='网页暂时无法连接桥接 · 正在重试';$('bridge-status').style.color='#d0b78b';$('connection-result').textContent=(e.message||String(e))+'\n请确认 DMI-Web.exe 正在运行，并使用主机提供的当前局域网地址。';currentFrame=null;try{runtime({Fresh:false})}catch{}return}
 refreshControlLinks();$('bridge-status').textContent=data.fresh?'TSW 7 已连接':data.enabled?'桥接已连接 · 等待 TSW 7':'桥接已连接 · 游戏连接已暂停';$('bridge-status').style.color=data.fresh?'#9cc4a6':'#d0b78b';$('connection-result').textContent=data.enabled?(data.fresh?'TSW 数据有效':'正在自动连接 TSW 7')+(data.error?'\n'+data.error:''):'连接已暂停。点击“连接并应用”恢复自动连接。';
 try{runtime(frame)}catch(e){$('connection-result').textContent+='\n页面显示异常：'+e.message+'。请刷新页面；桥接仍已连接。'}
 }finally{checking=false}}
async function boot(){cfg=C.saveConfig(cfg);populate();navigate();try{let j=await C.api.init();canManageConnection=j.canManageConnection!==false;refreshControlLinks();if(j.settings)for(let [k,v]of Object.entries(j.settings))if($(k))$(k).value=v;
 if(!canManageConnection){$('connection-admin').hidden=true;document.querySelector('nav a[href="#diagnostics"]').hidden=true;for(let id of ['connect','disconnect','query','list','raw'])$(id).disabled=true;$('lan-access').textContent='通过局域网读取主机的 TSW 7 数据。游戏连接由主机管理，此设备可调整界面与声音，可直接操作制动、ATO 和 PID，无需授权链接。';navigate()}
 else {let box=$('lan-access');box.replaceChildren();if(j.lanUrls&&j.lanUrls.length){box.append('局域网主屏：');for(let url of j.lanUrls){let a=document.createElement('a');a.href=url;a.textContent=url;box.append(a,document.createElement('br'))}}else box.textContent='未检测到可用的局域网 IPv4 地址。'}
 }catch{}await checkBridge();setInterval(checkBridge,1500)}boot();

function routeRuntime(f){$('system-summary').textContent='组件：'+(f.Cab?.systems?.join('、')||'未识别')+'\n'+(f.Cab?.active?'车载允许速度 '+Math.round(f.Cab.permitted)+' km/h':'车载限速未激活或接口未提供')+'\n'+(f.Supervision?.source||'等待线路数据');$('route-current').textContent=f.RouteId?'当前线路标识：'+f.RouteId:'等待游戏地图原点';$('brake-summary').textContent=(f.Vehicle||'等待车辆')+' · '+(f.Brake?.supported?'制动映射已配置':'正在自动识别游戏操纵控件');if(f.RouteId&&editingRoute!==f.RouteId){editingRoute=f.RouteId;let p=f.RouteProfile||cfg.routeProfiles?.[f.RouteId]||{device:'CTCS-2',level:2,mode:'FS'};$('route-device').value=p.device;$('route-level').value=p.level;$('route-mode').value=p.mode;$('route-system').value=p.system||'AUTO'}$('save-route').disabled=!canManageConnection||!f.Fresh||!f.RouteId}
$('save-route').onclick=async()=>{if(!currentFrame?.Fresh||currentFrame.RouteId!==editingRoute)return notice('线路已变化，请等待新数据',true);cfg.autoRoute=$('autoRoute').checked;let device=$('route-device').value,level=Number($('route-level').value);try{let result=await C.api.post('/api/route-profile',{routeId:editingRoute,device,level,mode:$('route-mode').value,system:$('route-system').value});cfg=C.saveConfig(cfg);notice(result.message)}catch(e){notice(e.message,true)}};
$('autoRoute').onchange=()=>{cfg.autoRoute=$('autoRoute').checked;cfg=C.saveConfig(cfg)};
for(let [id,name]of [['test-s1','S1_toofast'],['test-s2','S2_warning'],['test-info','S_info']])$(id).onclick=async()=>{await sound.unlock();await sound.loading;sound.play(name,cfg.volume);if(sound.error)notice(sound.error,true)};

for(const name of Object.keys(DmiSound.catalog)){const option=document.createElement('option');option.value=name;option.textContent=name;$('lkj-sample').appendChild(option)}
$('lkj-play').onclick=async()=>{try{await sound.unlock();const name=$('lkj-sample').value;if(await sound.speak(name,cfg.volume))notice('正在试听：'+name);else if(sound.error)notice(sound.error,true)}catch(e){notice(e.message,true)}};
$('lkj-stop').onclick=()=>{sound.stopVoice();notice('已停止试听')};
